    (P f np vp ecA : Z) (mb : byte) (name value : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo shi : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (spa : Z) (gsz : nat) (lj gj : list byte),
  rw_cells bsegs m1 spa [CB 56 lj] ->
  rw_cells bsegs m1 (spa + 56) [CB gsz gj] ->
  rw_cells bsegs m1 (bv_unsigned sp + -104) (otf_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  stk bsegs m1 lo spa -> munch [(lo, bv_unsigned sp)]%Z m m1 -> wmono bsegs m m1 -> mem_inv bsegs m1 ->
  spa + 56 + Z.of_nat gsz = bv_unsigned sp + -104 -> bv_unsigned sp - 176 <= spa -> spa mod 32 = 0 ->
  (* [comment removed for export] *)
  AFieldsC m1 (P + 80) S L ns ls em -> AFieldsOwn LB em -> FT m1 -> rw_cells bsegs m1 (P + 242) [C1 mb] ->
  bytes_at bsegs m1 np name -> np + zlength name < 2^64 ->
  0 <= f < 2^64 -> 0 <= vp < 2^64 -> zlength value < 2^64 -> 0 <= ecA < 2^64 ->
  lo + OTF_SEGA_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m1 ->
  as_RHEAP H s LB m1 -> as_RFS H LF m1 -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m1 lo shi -> bv_unsigned sp <= shi ->
  0 <= P -> aobj LB LF (P + 80) 48 -> aobj LB LF (P + 242) 1 -> accessible m1 (P + 242) 1 ->
  aobj LB LF np (zlength name) -> accessible m1 np (zlength name) ->
  bv_unsigned mb <= 1 -> (length LF + 1 < AFS_MAXLIVE)%nat ->
  evt bsegs (otf_segA_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF P f np vp ecA name value S L ns ls em lo shi m)
    (MS (mkR ra (Z_to_bv 64 spa) gp tp t0 t1 t2 sp s1 (Z_to_bv 64 P) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name))
              (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) (Z_to_bv 64 ecA) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xb9c30) fc None m1 (seg_rom bsegs)).
